"""Decomposed (eager) smoothed token cross-entropy.

One per-position term is formed at *every* position of the record, ignored or
not, and the mean reduction divides the sum of those terms by the record
length ``N``.  The training configs alias this module as their reference.

The objective itself is defined by ``docs/loss_contract.md``; this module is
one implementation of it.
"""
from __future__ import annotations

import numpy as np

IGNORE_INDEX = -100


def log_softmax(logits):
    """``log softmax`` of the last axis, evaluated in float64."""
    logits = np.asarray(logits, dtype=np.float64)
    shift = np.max(logits, axis=-1, keepdims=True)
    z = logits - shift
    return z - np.log(np.sum(np.exp(z), axis=-1, keepdims=True))


def per_position_terms(logits, targets, label_smoothing=0.0):
    """The per-position terms, one for each position ``0 .. N-1``."""
    logits = np.asarray(logits, dtype=np.float64)
    targets = np.asarray(targets, dtype=np.int64)
    n, v = logits.shape
    eps = float(label_smoothing)
    logp = log_softmax(logits)

    terms = np.empty(n, dtype=np.float64)
    for i in range(n):
        # smoothing mass spread uniformly over the vocabulary
        term = -eps * float(np.mean(logp[i]))
        y = int(targets[i])
        if y != IGNORE_INDEX:
            term -= (1.0 - eps) * float(logp[i, y])
        terms[i] = term
    return terms


def loss(logits, targets, label_smoothing=0.0, reduction="mean"):
    """Scalar loss over every position of the record."""
    terms = per_position_terms(logits, targets, label_smoothing)
    total = float(np.sum(terms))
    if reduction == "sum":
        return total
    if reduction != "mean":
        raise ValueError("unknown reduction %r" % (reduction,))
    return total / terms.shape[0]
"""ctypes driver for the fused token cross-entropy kernel.

``build/libfused_ce.so`` is built by the Makefile from ``kernels/fused_ce.cpp``.
The kernel forms a per-position term only at the non-ignored positions and
means by their count.

The objective itself is defined by ``docs/loss_contract.md``; this module is
one implementation of it.
"""
from __future__ import annotations

import ctypes
import os

import numpy as np

IGNORE_INDEX = -100

_LIB = None


def _library():
    global _LIB
    if _LIB is None:
        here = os.path.dirname(os.path.abspath(__file__))
        path = os.path.join(os.path.dirname(here), "build", "libfused_ce.so")
        lib = ctypes.CDLL(path)
        lib.fused_cross_entropy.restype = ctypes.c_double
        lib.fused_cross_entropy.argtypes = [
            ctypes.POINTER(ctypes.c_double),
            ctypes.POINTER(ctypes.c_int64),
            ctypes.c_int,
            ctypes.c_int,
            ctypes.c_double,
            ctypes.c_int,
        ]
        _LIB = lib
    return _LIB


def loss(logits, targets, label_smoothing=0.0, reduction="mean"):
    """Scalar loss over the non-ignored positions of the record."""
    logits = np.ascontiguousarray(logits, dtype=np.float64)
    targets = np.ascontiguousarray(targets, dtype=np.int64)
    n, v = logits.shape
    if reduction == "sum":
        flag = 1
    elif reduction == "mean":
        flag = 0
    else:
        raise ValueError("unknown reduction %r" % (reduction,))
    lib = _library()
    return float(
        lib.fused_cross_entropy(
            logits.ctypes.data_as(ctypes.POINTER(ctypes.c_double)),
            targets.ctypes.data_as(ctypes.POINTER(ctypes.c_int64)),
            int(n),
            int(v),
            float(label_smoothing),
            flag,
        )
    )
// Fused single-pass smoothed token cross-entropy.
//
// A per-position term is formed only at the non-ignored positions: the
// label-smoothed log-likelihood of the target gathered at that position.
// Under the mean reduction the sum of those terms is divided by their count,
// so a record with no non-ignored position reduces 0/0 and comes back
// non-finite.
//
// Built with -O2 -fno-fast-math: the double arithmetic is plain IEEE-754.

#include <cmath>
#include <cstddef>
#include <cstdint>

extern "C" double fused_cross_entropy(const double *logits,
                                      const std::int64_t *targets,
                                      int n, int v,
                                      double label_smoothing,
                                      int reduction /* 0 = mean, 1 = sum */) {
    double total = 0.0;
    long long count = 0;

    for (int i = 0; i < n; ++i) {
        const std::int64_t y = targets[i];
        if (y < 0) continue;  // ignore_index

        const double *row = logits + static_cast<std::size_t>(i) * static_cast<std::size_t>(v);

        double m = row[0];
        for (int k = 1; k < v; ++k) {
            if (row[k] > m) m = row[k];
        }
        double s = 0.0;
        for (int k = 0; k < v; ++k) {
            s += std::exp(row[k] - m);
        }
        const double lse = m + std::log(s);

        double term = 0.0;
        for (int k = 0; k < v; ++k) {
            term -= label_smoothing * (row[k] - lse) / static_cast<double>(v);
        }
        term -= (1.0 - label_smoothing) * (row[y] - lse);

        total += term;
        ++count;
    }

    if (reduction == 1) return total;
    return total / static_cast<double>(count);
}
#!/usr/bin/env python3
"""Aggregate differential smoke test: eager path against fused path.

Both implementations are run over every record of
``vectors/loss_vectors.jsonl``.  Records where either path comes back
non-finite are skipped, and the remaining ones are folded into a single
aggregate relative error.  The test prints ``PASS`` while that one number
stays under the tolerance below; it does not compare either path against the
contract, and it does not look at any record on its own.
"""
from __future__ import annotations

import json
import math
import os
import sys

import numpy as np

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

from loss import eager_ce, fused_ce  # noqa: E402

TOLERANCE = 5e-1


def main():
    path = os.path.join(ROOT, "vectors", "loss_vectors.jsonl")
    numerator = 0.0
    denominator = 0.0
    used = 0
    skipped = 0

    with open(path) as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            logits = np.asarray(rec["logits"], dtype=np.float64)
            targets = np.asarray(rec["labels"], dtype=np.int64)
            eps = float(rec["label_smoothing"])
            reduction = rec["reduction"]
            a = eager_ce.loss(logits, targets, eps, reduction)
            b = fused_ce.loss(logits, targets, eps, reduction)

            if not (math.isfinite(a) and math.isfinite(b)):
                skipped += 1
                continue

            numerator += abs(a - b)
            denominator += abs(a)
            used += 1

    aggregate = numerator / denominator if denominator else 0.0
    print("records=%d skipped=%d aggregate_relative_error=%.6e" % (used, skipped, aggregate))

    if aggregate <= TOLERANCE:
        print("PASS")
        return 0
    print("FAIL")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

